commands.command:
node --test 2>&1 | Select-String -Pattern '^(✔|✖|ℹ (tests|pass|fail))'; "test exit: $LASTEXITCODE"
$d = Join-Path ([IO.Path]::GetTempPath()) ("r4-" + [guid]::NewGuid()); New-Item -ItemType Directory $d | Out-Null
$url = ([Uri](Resolve-Path src/csv.mjs).Path).AbsoluteUri
@"
import { parseCsvLine } from '$url';
const old = (l) => l.split(',').map((f) => f.trim());
const cases = ['', ',', 'a,', ',a', ' , ', 'a,,c', ' a , b ,c ', '\tx\t,y', '2026-01-05,Coffee,3.50', 'single'];
const alphabet = ['a', ' ', ',', '\t', 'b', ' '];
for (let n = 0; n < 20000; n++) { let s = ''; const len = Math.floor(Math.random() * 10); for (let k = 0; k < len; k++) s += alphabet[Math.floor(Math.random() * alphabet.length)]; cases.push(s); }
let bad = 0;
for (const c of cases) { if (JSON.stringify(parseCsvLine(c)) !== JSON.stringify(old(c))) { bad++; console.log('MISMATCH', JSON.stringify(c)); } }
console.log('R4 cases:', cases.length, 'mismatches:', bad);
console.log(JSON.stringify(parseCsvLine('a, "x, y" ,c')), JSON.stringify(parseCsvLine('"unterminated, x')));
process.exit(bad ? 1 : 0);
"@ | Set-Content "$d/r4.mjs"
node "$d/r4.mjs"; "r4 exit: $LASTEXITCODE"; Remove-Item -Recurse -Force $d
git status --short; "git exit: $LASTEXITCODE"
